   334→                                                        block_root,
   335→                                                        index: data_column_sidecar.index,
   336→                                                    };
   337→
   338→                                                    received_data_column_sidecars.insert(identifier, slot);
   339→                                                    data_column_sidecars.push(data_column_sidecar);
   340→                                                }
   341→                                            }
